package com.myf.alert.controller; import com.myf.alert.entity.AlertaStock; import com.myf.alert.repository.AlertaRepository; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.LocalDateTime; import java.util.*;
@RestController @RequestMapping("/api/alertas") public class AlertaController { private final AlertaRepository r; public AlertaController(AlertaRepository r){this.r=r;} @GetMapping public List<AlertaStock> pendientes(){return r.findByEstadoOrderByFechaAlertaDesc("PENDIENTE");} @PutMapping("/{id}/atender") public ResponseEntity<?> atender(@PathVariable Long id){return r.findById(id).<ResponseEntity<?>>map(a->{a.setEstado("ATENDIDA");a.setFechaAtendida(LocalDateTime.now());return ResponseEntity.ok(r.save(a));}).orElseGet(()->ResponseEntity.notFound().build());} }
